-- Allow WITHDRAWN as an application status.
--
-- The check constraint on job_applications.status was generated by Hibernate
-- (ddl-auto: update) when the enum had five values. V7 added WITHDRAWN to the
-- Java enum, but ddl-auto never rewrites an existing check constraint, so every
-- withdrawal (by a candidate, or when a candidate deletes their account) failed
-- with "violates check constraint job_applications_status_check".
ALTER TABLE job_applications DROP CONSTRAINT IF EXISTS job_applications_status_check;

ALTER TABLE job_applications
    ADD CONSTRAINT job_applications_status_check
    CHECK (status IN ('APPLIED', 'REVIEWED', 'INTERVIEW', 'HIRED', 'REJECTED', 'WITHDRAWN'));
